// Cyrus R5: the TEST FLIGHT GATE (pure half). After a build succeeds and scans clean, the worker boots it once on a
// disposable Paper server for the build's own version (node-2, ./client.ts) with its jar, its data packs and (when the
// Pack Loader jar is available) its pack config, and stores an HONEST per-check result on the build:
//   compile, scan, boot, plugins enabled, commands registered, data pack loaded  (each pass / fail / not_run)
// "not run" is never shown as passed; the verdict only ever feeds a "boot-tested on <version>" label (a boot proves
// the plugin loads and its commands register, never how it behaves in game). Optional: block publishing / installing a
// build whose flight FAILED (CYRUS_TESTFLIGHT_BLOCK_ON_FAIL=1).
// Flags (all OFF): CYRUS_TESTFLIGHT_GATE=1 runs flights; CYRUS_TESTFLIGHT_BLOCK_ON_FAIL=1 blocks on a failed flight.
// Limits: one flight at a time per worker (node-2 runs one anyway; "busy" is retried with backoff), at most
// MAX_FLIGHTS_PER_BUILD real flights per build (per-build cost cap) and MAX_BUSY_RETRIES busy retries.
import { getVersion } from "../versions/registry";
import type { CheckResult, RconCheck, TestFlightReport, TestFlightSpec, TestFlightSummary } from "./types";
import { stressBlocks, type StoredStress } from "./stress";
import type { StoredWorldgen } from "./worldgen";

export const GATE_FLAG = "CYRUS_TESTFLIGHT_GATE";
export const BLOCK_FLAG = "CYRUS_TESTFLIGHT_BLOCK_ON_FAIL";
export const MAX_FLIGHTS_PER_BUILD = 2;
export const MAX_BUSY_RETRIES = 12;
export const MAX_COMMAND_CHECKS = 8;
export const GATE_VERSION = "tfgate-1";

export const GATE_CHECKS = ["compile", "scan", "boot", "plugins_enabled", "commands_registered", "datapack_loaded"] as const;
export type GateCheckId = (typeof GATE_CHECKS)[number];
export type GateCheck = { id: GateCheckId; status: "pass" | "fail" | "not_run"; detail: string };
export type GateVerdict = "passed" | "failed" | "incomplete" | "not_run";

/** What is stored on ModBuild.cyrus.testFlight (plain JSON, small). */
export type StoredFlight = {
  schema: 1;
  gate: string;
  state: "queued" | "running" | "done" | "not_run" | "gave_up";
  version: string;
  verdict: GateVerdict;
  /** "boot-tested on Paper <version>" only when every required check passed; never about in-game behaviour. */
  label: string | null;
  checks: GateCheck[];
  reason?: string;
  flights: number;
  busyRetries: number;
  nextAt?: string;
  lastError?: string;
  runId?: string | null;
  bootMs?: number | null;
  peakRssKb?: number | null;
  engine?: { runner?: string; paperBuild?: number; jdk?: string | null } | null;
  notes?: string[];
  /** Wiring 2 (CYRUS_PLAYTEST): the playtest bots' verdict from the build's stored ModSpec, kept APART from the boot
   *  verdict (a playtest never changes `verdict` / `label`). Absent = the switch was off. */
  playtest?: { verdict: "passed" | "failed" | "incomplete" | "not_run"; label: string; counts?: { planned: number; ran: number; passed: number; failed: number; notRun: number }; scenarios?: { id: string; status: string; reason: string | null }[]; specRevisionId?: string | null } | null;
  /** R42: the vanilla reference checks of the build's packs (copied from ModBuild.result.assets.vanilla). Never changes
   *  `verdict` / `label`: a pack that overrides vanilla still boots; this is a warning for the owner and the customer. */
  vanilla?: { status: "checked" | "not_run"; version: string; counts: { error: number; warn: number; info: number }; issues: { code: string; severity: string; path: string; message: string }[] } | null;
  /** Perf safety: the STRESS phase (./stress.ts storedStress), kept apart from the boot verdict. A FAILED stress blocks
   *  Install by default (flightBlocks). Absent = not flown (switch off or an older flight). */
  stress?: StoredStress | null;
  /** tf-lite-6 (CYRUS_TESTFLIGHT_WORLDGEN=1): worldgen density probes of the build's data packs (./worldgen.ts). Informational:
   *  never changes `verdict` / `label` and never blocks Install. Absent = switched off or no probe-able feature. */
  worldgen?: StoredWorldgen | null;
  at: string;
};

export type GateBuild = {
  id: string; mcVersion: string; pluginName: string | null; jarSha256: string | null;
  /** ModBuild.result: commands + safety are read from it. */
  result: unknown;
};
export type GateArtifacts = {
  jarPath: string;
  /** spec + namespace (optional): the data pack spec it was built from, for the worldgen density probes. */
  datapacks: { name: string; localPath: string; spec?: unknown; namespace?: string }[];
  /** The Pack Loader jar + the packs.json this build's pack would get (when both are available). */
  packLoader?: { localPath: string; sha256: string; config: string } | null;
};

/** Can this version be test-flown at all? (a pinned Paper SERVER build is needed). */
export function flightVersion(v: string): { ok: true } | { ok: false; reason: string } {
  const row = getVersion(v);
  if (!row) return { ok: false, reason: `not run: ${v} is not in the version registry` };
  if (!row.paperBuild || !row.paperServerSha256) return { ok: false, reason: `not run: no test server for ${v} (no pinned Paper server build)` };
  return { ok: true };
}

type Cmd = { usage?: string };
/** Command labels the build says it has (from ModBuild.result.commands usage, e.g. "/alpha give <p>" -> alpha). */
export function commandLabels(result: unknown): string[] {
  const cmds = ((result as { commands?: Cmd[] } | null)?.commands ?? []) as Cmd[];
  const out: string[] = [];
  for (const c of cmds) {
    const m = /^\/([a-z0-9_-]{1,32})(?:\s|$)/i.exec(String(c?.usage ?? "").trim());
    if (m && !out.includes(m[1].toLowerCase())) out.push(m[1].toLowerCase());
  }
  return out.slice(0, MAX_COMMAND_CHECKS);
}

export function scanVerdict(result: unknown): "pass" | "warn" | "block" | null {
  const v = (result as { safety?: { verdict?: string } | null } | null)?.safety?.verdict;
  return v === "pass" || v === "warn" || v === "block" ? v : null;
}

/** The flight spec for one build, or why it is not run. */
export function planGateFlight(b: GateBuild, art: GateArtifacts): { ok: true; spec: TestFlightSpec; commands: string[] } | { ok: false; reason: string } {
  const fv = flightVersion(b.mcVersion);
  if (!fv.ok) return fv;
  if (!b.pluginName) return { ok: false, reason: "not run: the build has no plugin name" };
  const sv = scanVerdict(b.result);
  if (sv === "block") return { ok: false, reason: "not run: the safety scan blocked this build" };
  const commands = commandLabels(b.result);
  const rcon: RconCheck[] = [
    { id: "plugins", command: "plugins", expect: [b.pluginName] },
    // Paper answers `help <label>` with the command's help topic when it is registered, "No help for" otherwise
    ...commands.map((c) => ({ id: `cmd-${c}`, command: `help ${c}`, expectNot: ["No help for"], required: false })),
  ];
  const plugins: TestFlightSpec["plugins"] = [{ localPath: art.jarPath, ...(b.jarSha256 ? { sha256: b.jarSha256 } : {}) }];
  const files: TestFlightSpec["files"] = [];
  if (art.packLoader) {
    plugins.push({ localPath: art.packLoader.localPath, sha256: art.packLoader.sha256 });
    files.push({ path: "plugins/NxeonPackLoader/packs.json", content: art.packLoader.config });
    rcon.push({ id: "packs", command: "nxpacks status", expect: ["config=ok"], required: false });
  }
  return { ok: true, commands, spec: { version: b.mcVersion, plugins, datapacks: art.datapacks.map((d) => ({ name: d.name, localPath: d.localPath })), ...(files.length ? { files } : {}), rcon, timeouts: { bootSec: 180, totalSec: 420 } } };
}

const check = (r: TestFlightReport, id: CheckResult["id"]) => r.checks.find((c) => c.id === id) ?? null;
const ev = (c: CheckResult | null, n = 2) => (c ? c.evidence.slice(0, n).join(" | ").slice(0, 300) : "");

/** Map one flight to the six honest statuses. */
export function gateChecks(b: GateBuild, r: TestFlightReport | null, s: TestFlightSummary | null, o: { commands: string[]; datapacks: number; reason?: string }): GateCheck[] {
  const sv = scanVerdict(b.result);
  const nr = (id: GateCheckId, detail: string): GateCheck => ({ id, status: "not_run", detail });
  const out: GateCheck[] = [
    { id: "compile", status: "pass", detail: "compiled by the build service" },
    sv === null ? nr("scan", "no scan result stored") : { id: "scan", status: sv === "block" ? "fail" : "pass", detail: sv === "warn" ? "passed with warnings" : sv === "block" ? "blocked by the safety scan" : "clean" },
  ];
  if (!r || r.status !== "completed" || !s) {
    const why = o.reason ?? (r?.status === "busy" ? "not run: the test server was busy" : r ? `not run: ${r.status}` : "not run");
    return [...out, nr("boot", why), nr("plugins_enabled", why), nr("commands_registered", why), nr("datapack_loaded", o.datapacks ? why : "no data pack in this build")];
  }
  const boot = check(r, "boot_done"), pe = check(r, "plugins_enabled"), rc = check(r, "rcon_checks");
  const st = (c: CheckResult | null): GateCheck["status"] => (!c ? "not_run" : c.status === "pass" && c.evidence.length ? "pass" : c.status === "fail" ? "fail" : "not_run");
  out.push({ id: "boot", status: st(boot), detail: ev(boot) || "no evidence" });
  out.push({ id: "plugins_enabled", status: st(pe), detail: ev(pe) || "no evidence" });
  // commands: each `cmd-<label>` evidence line says ok / FAILED; none sent = not_run
  const lines = rc?.evidence ?? [];
  const cmdLines = o.commands.map((c) => lines.find((l) => l.startsWith(`cmd-${c} `)) ?? null);
  if (!o.commands.length) out.push(nr("commands_registered", "the build lists no commands"));
  else if (cmdLines.some((l) => l === null)) out.push(nr("commands_registered", `${cmdLines.filter((l) => l === null).length} command check(s) did not run`));
  else out.push({ id: "commands_registered", status: cmdLines.every((l) => /: ok/.test(l!)) ? "pass" : "fail", detail: cmdLines.map((l) => l!.slice(0, 80)).join(" | ").slice(0, 300) });
  if (!o.datapacks) out.push(nr("datapack_loaded", "no data pack in this build"));
  else {
    const dl = lines.find((l) => l.startsWith("datapacks-enabled "));
    out.push(dl ? { id: "datapack_loaded", status: /: ok/.test(dl) ? "pass" : "fail", detail: dl.slice(0, 300) } : nr("datapack_loaded", "the data pack check did not run"));
  }
  return out;
}

/** Verdict + label from the runner summary (the summary already refuses success when a required stage was skipped). */
export function gateVerdict(s: TestFlightSummary | null, checks: GateCheck[]): { verdict: GateVerdict; label: string | null } {
  if (!s) return { verdict: "not_run", label: null };
  if (s.overall === "busy" || s.overall === "error") return { verdict: "not_run", label: null };
  const anyFail = checks.some((c) => c.status === "fail" && c.id !== "commands_registered") || s.overall === "failed";
  if (anyFail) return { verdict: "failed", label: null };
  if (!s.success) return { verdict: "incomplete", label: null };
  return { verdict: "passed", label: `boot-tested on Paper ${s.version}` };
}

/** R42: the build's vanilla check summary (ModBuild.result.assets.vanilla), trimmed for the flight record. null = not run. */
export function vanillaOf(result: unknown): StoredFlight["vanilla"] {
  const v = (result as { assets?: { vanilla?: unknown } } | null)?.assets?.vanilla as NonNullable<StoredFlight["vanilla"]> | undefined;
  if (!v || typeof v !== "object" || (v.status !== "checked" && v.status !== "not_run") || !v.counts) return null;
  return { status: v.status, version: String(v.version), counts: { error: Number(v.counts.error) || 0, warn: Number(v.counts.warn) || 0, info: Number(v.counts.info) || 0 }, issues: (Array.isArray(v.issues) ? v.issues : []).slice(0, 8) };
}
/** One note line for a checked summary with problems, or null. */
export function vanillaNote(v: StoredFlight["vanilla"]): string | null {
  if (!v || v.status !== "checked" || !(v.counts.error + v.counts.warn)) return null;
  return `vanilla check (${v.version}): ${v.counts.error} error(s), ${v.counts.warn} warning(s)${v.issues[0] ? `, e.g. ${v.issues[0].path}: ${v.issues[0].message}` : ""}`.slice(0, 300);
}

export const backoffMs = (busyRetries: number) => Math.min(10 * 60_000, 30_000 * 2 ** Math.max(0, busyRetries));

/** Read a stored result back (tolerant). */
export function readStoredFlight(raw: unknown): StoredFlight | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const r = raw as StoredFlight;
  return r.schema === 1 && typeof r.state === "string" && Array.isArray(r.checks) ? r : null;
}

/** Is this build due a flight now? (pure scheduling) */
export function dueForFlight(stored: StoredFlight | null, now: Date): boolean {
  if (!stored) return true;
  if (stored.state === "queued") return !stored.nextAt || new Date(stored.nextAt).getTime() <= now.getTime();
  if (stored.state === "running") return new Date(stored.at).getTime() < now.getTime() - 30 * 60_000; // a worker died mid-flight
  return false;
}

/** Optional gate on publish / install: only a FAILED flight blocks, and only with the flag on. "Not run" never blocks. */
export function flightBlocks(stored: unknown, env: Record<string, string | undefined> = process.env): { blocked: false } | { blocked: true; reason: string } {
  const f = readStoredFlight(stored);
  // perf safety: a FAILED stress test blocks by default, independent of CYRUS_TESTFLIGHT_BLOCK_ON_FAIL (CYRUS_PERF_BLOCK_ON_FAIL=0 = off)
  if (f?.state === "done" && f.stress) { const sb = stressBlocks(f.stress, f.version, env); if (sb.blocked) return sb; }
  if (env[BLOCK_FLAG] !== "1") return { blocked: false };
  if (f?.state === "done" && f.verdict === "failed") {
    const bad = f.checks.filter((c) => c.status === "fail").map((c) => c.id.replace(/_/g, " "));
    return { blocked: true, reason: `This version failed its Test Flight on Paper ${f.version} (${bad.join(", ") || "boot"}). Fix it with a change request before installing or publishing it.` };
  }
  return { blocked: false };
}

/** Customer-facing lines for the NxLabs mod page (honest: not run is never shown as passed). */
export function flightLines(stored: unknown): string[] {
  const f = readStoredFlight(stored);
  if (!f) return [];
  const name: Record<GateCheckId, string> = { compile: "Compiles", scan: "Safety scan", boot: "Server boots", plugins_enabled: "Plugin enables", commands_registered: "Commands register", datapack_loaded: "Data pack loads" };
  const word = { pass: "passed", fail: "FAILED", not_run: "not run" } as const;
  const head = f.label ? `Boot-tested on Paper ${f.version} (a real server started with this version; this does not test gameplay).`
    : f.verdict === "failed" ? `Failed its boot test on Paper ${f.version}.`
    : f.state === "queued" || f.state === "running" ? `Boot test on Paper ${f.version} is queued.`
    : `Not boot-tested${f.reason ? `: ${f.reason.replace(/^not run: /, "")}` : ""}.`;
  return [head, ...f.checks.map((c) => `${name[c.id]}: ${word[c.status]}`), ...(f.stress ? [f.stress.label] : []), ...(f.worldgen ? [f.worldgen.label] : [])];
}

#!/usr/bin/env tsx
// Bundle mc-coverage: can Cyrus animated creatures run on Minecraft 1.21.x? Boots ONE real Paper server on node-2 (Test
// Flight, no internet) with the BetterModel 2.2.0 paper jar (MIT, Java 21 classes, the last release line before 3.x
// moved to 26.x/Java 25), its runtime libraries SEEDED (resolve-libraries.sh), the creature fixture plugin compiled
// against that version's Paper API + the BetterModel jar, and a Cyrus-compiled .bbmodel (the banshee example). Same RCON
// script as the 26.2 creature flights. Server side only: no client sees the model.
//   npx tsx scripts/cyrus/bettermodel-121x-flight.ts 1.21.11 [--bm 2.2.0] [--out FILE]
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { runTestFlight, NODE2 } from "../../lib/cyrus/testflight/client";
import { checkRigSpec } from "../../lib/cyrus/creature/spec";
import { compileCreature } from "../../lib/cyrus/creature/compile";
import type { TestFlightSpec } from "../../lib/cyrus/testflight/types";


/** One flight at a time on node-2: when another agent's flight holds the runner lock, wait and retry (max ~20 min). */
async function flyWhenFree(spec: TestFlightSpec) {
  for (let i = 0; ; i++) {
    const r = await runTestFlight(spec);
    if (r.report.status !== "busy" || i >= 40) return r;
    await new Promise((res) => setTimeout(res, 30000));
  }
}

const ROOT = path.resolve(__dirname, "../..");
const argv = process.argv.slice(2);
const opt = (n: string, d: string) => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] ? argv[i + 1] : d; };
const V = argv[0] ?? "1.21.11";
const BM = opt("bm", "2.2.0");
const TF = "/tank/nxeon-build/tmp/testflight";
const ssh = (cmd: string, input?: Buffer) => execFileSync("ssh", ["-o", "BatchMode=yes", "-o", "ConnectTimeout=15", NODE2, cmd], { encoding: "utf8", maxBuffer: 64 * 1024 * 1024, input });

async function main() {
  const NS = "nx_r6cr34tr";
  const spec = JSON.parse(readFileSync(path.join(ROOT, "services/modbuilder/creature-example.json"), "utf8"));
  const chk = checkRigSpec(spec, { namespace: NS });
  if (!chk.ok) throw new Error(chk.error);
  const c = compileCreature(chk.spec, NS, {});
  if (!c.ok) throw new Error(c.error);
  const key = c.creature.key;
  const bmJar = `${TF}/bettermodel/BetterModel-${BM}-paper.jar`;
  // Compile the fixture on node-2 against this version's API classpath + the BetterModel jar (compile-only).
  const fx = `${TF}/inbox/mc1-bm-${V.replace(/\./g, "-")}`;
  const fixtureTar = execFileSync("tar", ["-C", path.join(ROOT, "services/modbuilder/tools/testflight/fixtures/creature"), "-cf", "-", "."]);
  const build = ssh([
    `set -e; rm -rf ${fx}; mkdir -p ${fx}/src`,
    `tar --no-same-owner -xf - -C ${fx}/src`,
    `test -f ${fx}/src/plugin.yml`,
    // compile like the build service: Paper API + the allowlisted BetterModel 2.x API jars (lib/cyrus/import/deps.json), not the plugin
    `printf '%s:%s:%s' "$(cat /tank/nxeon-build/tmp/mc-coverage/cp/${V}.txt)" /tank/nxeon-build/tmp/mc-coverage/deps/bettermodel-api-${BM}.jar /tank/nxeon-build/tmp/mc-coverage/deps/bettermodel-bukkit-api-${BM}.jar > ${fx}/cp.txt`,
    `bash ${TF}/fixtures/build.sh ${fx}/src ${V} ${TF}/jdk/21 21 ${fx}/cp.txt ${fx}/TfCreature-${V}.jar`,
  ].join(" && "), fixtureTar);
  const fixtureSha = build.trim().split(/\s+/)[0];
  const rcon: TestFlightSpec["rcon"] = [
    { id: "difficulty", command: "difficulty easy", expect: ["difficulty"] },
    { id: "models", command: `tfcreature models ${key}`, expect: ["models=1", "has=true"] },
    { id: "spawn", command: `tfcreature spawn ${key} 1`, expect: ["spawned=1", "idle=1", "trackers=1"] },
    { id: "stats-1", command: "tfcreature stats", expect: ["trackersOpen=1"] },
    { id: "attack", command: `tfcreature attack ${NS}:banshee.attack`, expect: ["attack_started=1"] },
    { id: "hurt", command: `tfcreature hurt ${NS}:banshee.hurt`, expect: ["hurt_started=1"] },
    { id: "death", command: `tfcreature death ${NS}:banshee.death`, expect: ["death_started=1"] },
    { id: "spawn-10", command: `tfcreature spawn ${key} 10`, expect: ["spawned=10"] },
    { id: "stats-11", command: "tfcreature stats", expect: ["trackersOpen=11"] },
    { id: "despawn", command: "tfcreature despawn", expect: ["zombies=0"] },
    { id: "stats-end", command: "tfcreature stats", expect: ["trackersOpen=0"] },
    { id: "bm-reload", command: "bettermodel reload", required: false },
    { id: "pack-wait", command: "tfcreature models", waitMs: 8000, required: false },
    { id: "models-after-reload", command: `tfcreature models ${key}`, expect: ["has=true"] },
  ];
  const tf: TestFlightSpec = {
    version: V,
    plugins: [{ remotePath: bmJar }, { remotePath: `${fx}/TfCreature-${V}.jar`, sha256: fixtureSha }],
    seeds: [{ from: `bettermodel-${BM}-paper-libraries`, to: "libraries" }, { from: `bettermodel-${BM}-libby`, to: "plugins/BetterModel/.libs" }],
    files: [{ path: `plugins/BetterModel/models/${key}.bbmodel`, content: c.creature.bbmodel }],
    rcon, timeouts: { bootSec: 300, rconSec: 30, stopSec: 90, totalSec: 900 }, memory: { xmxMb: 1024, rssCapMb: 2048 },
    collect: ["plugins/BetterModel/config.yml", "plugins/BetterModel/", "plugins/BetterModel/build/", "logs/latest.log"],
  };
  const t0 = Date.now();
  const { report, summary } = await flyWhenFree(tf);
  try { ssh(`rm -rf ${fx}`); } catch { /* best effort */ }
  const ev = (id: string) => report.checks.find((x) => x.id === id)?.evidence ?? [];
  const out = {
    at: new Date().toISOString(), host: "node-2", realClient: false, version: V, bettermodel: `${BM} (${path.basename(bmJar)})`,
    creature: { key, bbmodelSha256: c.creature.bbmodelSha256, bytes: c.creature.bbmodel.length }, fixtureSha256: fixtureSha, wallMs: Date.now() - t0,
    summary, rcon: ev("rcon_checks"), plugins: ev("plugins_enabled"), log: ev("startup_log_clean"), collected: report.collected ?? [], engine: report.engine,
  };
  const file = opt("out", `/root/agent-notes/cyrus-research/bettermodel-121x-flights-2026-10-11.json`);
  let all: unknown[] = [];
  try { all = JSON.parse(readFileSync(file, "utf8")); } catch { all = []; }
  writeFileSync(file, JSON.stringify([...(Array.isArray(all) ? all : []), out], null, 1) + "\n");
  console.log(`${V} BetterModel ${BM}: ${summary.overall} (boot ${summary.bootMs} ms, peak ${Math.round((summary.peakRssKb ?? 0) / 1024)} MB) failed=${summary.failed.join(",") || "-"}`);
  for (const l of [...out.plugins.slice(0, 6), ...out.rcon, ...out.log.slice(0, 6)]) console.log("  " + l.slice(0, 260));
}

main().catch((e) => { console.error(e); process.exit(2); });
