/** Read a catalog artifact from CYRUS_MANAGED_PLUGIN_DIR and verify its sha256 against the pin. */
export async function readManagedArtifact(entry: CatalogEntry, dir = process.env.CYRUS_MANAGED_PLUGIN_DIR || ""): Promise<Buffer> {
  if (!dir || !path.isAbsolute(dir)) throw new Error("CYRUS_MANAGED_PLUGIN_DIR must be an absolute path");
  const p = path.join(dir, entry.artifact);
  if (!p.startsWith(path.resolve(dir) + path.sep)) throw new Error("artifact path escapes the managed plugin dir");
  const bytes = await readFile(p);
  const sha = createHash("sha256").update(bytes).digest("hex");
  if (sha !== entry.sha256) throw new Error(`${entry.key} ${entry.version}: artifact sha256 ${sha} does not match the pin ${entry.sha256}`);
  return bytes;
}

