// Perf safety stress coverage, SERVER ONLY (reads jars with node:zlib): kept apart from ./stress.ts so the pure stress
// module (imported by gate.ts, which client pages use) never pulls node built-ins into a browser bundle.
import { parseClass } from "../inventory/classfile";
import { addClass, emptySummary, finishSummary } from "../inventory/bytecode";
import { DEFAULT_ZIP_LIMITS, indexZip, readEntry } from "../inventory/zipread";

/** The mod's own event handlers + repeating task sites from its jar, WITHOUT the injected watchdog (<pkg>.nxperf.*). null = unreadable. */
export function modLoadProfile(jar: Buffer): { events: string[]; repeatingTasks: number } | null {
  const idx = indexZip(jar, DEFAULT_ZIP_LIMITS);
  if (!idx.ok) return null;
  const sum = emptySummary();
  const notes = new Map<string, number>();
  let n = 0;
  for (const e of idx.zip.entries) {
    if (e.dir || !e.name.endsWith(".class") || /(^|\/)nxperf\//.test(e.name)) continue;
    if (++n > 4000) break;
    const r = readEntry(idx.zip, e, 1024 * 1024);
    if (!r.ok) continue;
    const c = parseClass(r.data);
    if (c.ok) addClass(sum, c.cls, null, notes);
  }
  const f = finishSummary(sum, notes);
  return { events: [...new Set(f.events.map((x) => x.event))].sort(), repeatingTasks: f.repeatingTaskSites };
}

