export type PinResult = { ok: true; entry: CatalogEntry; family: Family } | { ok: false; code: "unknown_version" | "unknown_plugin" | "no_pin" | "java_too_old"; error: string };

/** The pinned entry for a plugin on a server running `mcVersion` (exact registry id). Fails closed. */
export function pinFor(entries: CatalogEntry[], key: string, mcVersion: string): PinResult {
  const v = getVersion(mcVersion);
  if (!v) return { ok: false, code: "unknown_version", error: `Minecraft ${mcVersion} is not in the version registry` };
  const forKey = entries.filter((e) => e.key === key);
  if (!forKey.length) return { ok: false, code: "unknown_plugin", error: `no managed plugin called ${key}` };
  const entry = forKey.find((e) => e.family === v.family);
  if (!entry) return { ok: false, code: "no_pin", error: `${key} has no pinned version for Minecraft ${v.family}.x` };
  if (entry.javaRelease > v.javaRelease) return { ok: false, code: "java_too_old", error: `${key} ${entry.version} needs Java ${entry.javaRelease}; Minecraft ${mcVersion} servers run Java ${v.javaRelease}` };
  return { ok: true, entry, family: v.family };
}

