// rc12: a build whose Test Flight FAILED (the goblin mod: "plugins_enabled failed") is shown honestly and never featured.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { flightFailureOf, flightFailedVerdict } from "../lib/cyrus/app/failure";

const failed = { schema: 1, gate: "tfgate-1", state: "done", verdict: "failed", label: null, version: "1.21.11", at: "2026-10-14T10:00:00Z",
  checks: [
    { id: "compile", status: "pass", detail: "ok" }, { id: "boot", status: "pass", detail: "ok" },
    { id: "plugins_enabled", status: "fail", detail: "Goblins: NOT enabled (enableError=true disabled=true)" },
  ] };

describe("flightFailureOf", () => {
  it("shows the honest banner with the reason, the check and a refine offer", () => {
    const v = flightFailureOf({ status: "succeeded", cyrus: { testFlight: failed } })!;
    assert.ok(v);
    assert.match(v.reason, /^This mod did not load in our test server: Goblins: NOT enabled/);
    assert.deepEqual(v.checks, ["plugin enable: failed"]);
    assert.equal(v.refine, true);
    assert.match(v.note, /not charging for the repair/);
    assert.match(v.note, /Refine/);
  });
  it("is silent for passed, queued, incomplete, not-run and non-succeeded builds", () => {
    for (const tf of [{ ...failed, verdict: "passed" }, { ...failed, state: "queued" }, { ...failed, verdict: "incomplete" }, { ...failed, state: "not_run", verdict: "not_run" }, null, undefined]) {
      assert.equal(flightFailureOf({ status: "succeeded", cyrus: { testFlight: tf } }), null);
    }
    assert.equal(flightFailureOf({ status: "failed", cyrus: { testFlight: failed } }), null);
    assert.equal(flightFailureOf(null), null);
    assert.equal(flightFailureOf({ status: "succeeded", cyrus: null }), null);
  });
  it("featured exclusion verdict", () => {
    assert.equal(flightFailedVerdict({ verdict: "failed" }), true);
    assert.equal(flightFailedVerdict({ verdict: "passed" }), false);
    assert.equal(flightFailedVerdict(undefined), false);
  });
});
