import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { makeZip } from "./_mods-zip-fixture.ts";
import { engineNeed, jarDependencies, provisionEngine } from "../lib/cyrus/testflight/engine";
