import type { CheckResult, TestFlightReport } from "../lib/cyrus/testflight/types";

const jarWith = (yml: string) => makeZip([{ name: "plugin.yml", data: yml }, { name: "a/B.class", data: Buffer.from([0xca, 0xfe, 0xba, 0xbe]) }]);
const fox = jarWith("name: FoxCompanion\nmain: a.B\nversion: 1\napi-version: '1.21'\ndepend: [BetterModel]\n");
const plain = jarWith("name: Plain\nmain: a.B\nversion: 1\napi-version: '1.21'\n");
const soft = jarWith("name: Soft\nmain: a.B\nversion: 1\nsoftdepend: [BetterModel]\n");
const bmBytes = Buffer.from("fake bettermodel jar");
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");

const build: GateBuild = { id: "mbx", mcVersion: "1.21.11", pluginName: "FoxCompanion", jarSha256: null, result: { safety: { verdict: "pass" }, commands: [{ usage: "/fox follow" }] } };

describe("engine need", () => {
  it("reads depend / softdepend from the jar and creature assets", () => {
    assert.deepEqual(jarDependencies(fox), { depend: ["BetterModel"], softdepend: [] });
    assert.match(engineNeed(fox, null)!, /depend: BetterModel/);
    assert.match(engineNeed(soft, null)!, /softdepend/);
    assert.equal(engineNeed(plain, []), null);
    assert.match(engineNeed(plain, [{}])!, /creatures/);
    assert.equal(engineNeed(Buffer.from("junk"), null), null);
  });
});

describe("provisionEngine", () => {
  it("resolves the pinned jar without downloading and wires seeds + config", async () => {
    // the catalog pins the sha: serve a reader that returns bytes (the pin check lives in readManagedArtifact)
    const p = await provisionEngine({ jar: fox, mcVersion: "1.21.11" }, { env: {}, readJar: async () => bmBytes });
    assert.ok(p && !p.unavailable);
    assert.equal(p!.version, "2.2.0");
    assert.equal(p!.jar!.sha256, sha(bmBytes));
    assert.deepEqual(p!.seeds!.map((s) => s.to), ["libraries", "plugins/BetterModel/.libs"]);
    assert.ok(p!.files!.some((f) => f.path === "plugins/BetterModel/config.yml"));
  });
  it("missing jar is unavailable, not a failure; no need is null", async () => {
    const p = await provisionEngine({ jar: fox, mcVersion: "1.21.11" }, { env: {}, readJar: async () => { throw new Error("ENOENT"); } });
    assert.match(p!.unavailable!, /jar is not available on this host/);
    assert.equal(await provisionEngine({ jar: plain, mcVersion: "1.21.11" }, { env: {} }), null);
  });
});

describe("planGateFlight with an engine", () => {
  const art = { jarPath: "/x/mod.jar", datapacks: [] };
  it("puts BetterModel first with seeds, files and more memory", () => {
    const r = planGateFlight(build, { ...art, engine: { name: "BetterModel", reason: "depend", localPath: "/x/BetterModel.jar", sha256: sha(bmBytes), seeds: [{ from: "s", to: "libraries" }], files: [{ path: "plugins/BetterModel/config.yml", content: "a: 1" }] } });
    assert.ok(r.ok);
    if (!r.ok) return;
    assert.equal(r.spec.plugins![0].localPath, "/x/BetterModel.jar");
    assert.equal(r.spec.plugins![1].localPath, "/x/mod.jar");
    assert.deepEqual(r.spec.seeds, [{ from: "s", to: "libraries" }]);
    assert.equal(r.spec.memory?.xmxMb, 1024);
  });
  it("unavailable jar = honest not_run", () => {
    const r = planGateFlight(build, { ...art, engine: { name: "BetterModel", reason: "depend", unavailable: "jar missing" } });
    assert.equal(r.ok, false);
    if (!r.ok) assert.match(r.reason, /^not run: BetterModel jar unavailable/);
  });
  it("no engine = unchanged spec", () => {
    const r = planGateFlight(build, art);
