    if (r.ok) { assert.equal(r.spec.plugins!.length, 1); assert.equal(r.spec.seeds, undefined); }
  });
});

function report(pe: { status: "pass" | "fail"; evidence: string[] }): TestFlightReport {
  const c = (id: string, status: "pass" | "fail", evidence: string[]) => ({ id, status, evidence, durationMs: 1 }) as unknown as CheckResult;
  return { status: "completed", version: "1.21.11", runId: "tf-x-abc123", bootMs: 1, peakRssKb: 1, checks: [c("boot_done", "pass", ["Done"]), c("plugins_enabled", pe.status, pe.evidence), c("startup_log_clean", "pass", ["ok"]), c("rcon_checks", "pass", ["cmd-fox: ok"])] } as unknown as TestFlightReport;
}
