    const r = report({ status: "fail", evidence: ["BetterModel: NOT enabled (log: enabling=true enableError=true loadError=false disabled=true; rcon plugins: false)", "FoxCompanion: NOT enabled (log: enabling=false enableError=false loadError=false disabled=false; rcon plugins: absent)"] });
    const s = summarize(spec(), r);
