    assert.equal(pe.status, "not_run");
    assert.match(pe.detail, /^engine plugin failed: BetterModel did not enable/);
    assert.equal(checks.find((c) => c.id === "commands_registered")!.status, "not_run");
    assert.notEqual(gateVerdict(s, checks).verdict, "failed");
  });
  it("engine ok, mod not enabled -> mod failure", () => {
    const r = report({ status: "fail", evidence: ["BetterModel: enabled (log: ...)", "FoxCompanion: NOT enabled (log: enableError=true)", "L9: java.lang.NoClassDefFoundError: kr/toxicity/Foo"] });
    const s = summarize(spec(), r);
    const checks = gateChecks(build, r, s, { commands: ["fox"], datapacks: 0, engine: "BetterModel", pluginName: "FoxCompanion" });
    const pe = checks.find((c) => c.id === "plugins_enabled")!;
    assert.equal(pe.status, "fail");
    assert.match(pe.detail, /missing dependency or class/);
    assert.equal(gateVerdict(s, checks).verdict, "failed");
  });
  it("both enabled -> pass", () => {
    const r = report({ status: "pass", evidence: ["BetterModel: enabled (log: ...)", "FoxCompanion: enabled (log: ...)"] });
    const s = summarize(spec(), r);
    const checks = gateChecks(build, r, s, { commands: ["fox"], datapacks: 0, engine: "BetterModel", pluginName: "FoxCompanion" });
    assert.equal(checks.find((c) => c.id === "plugins_enabled")!.status, "pass");
  });
});
