 *
 * These are behavioural checks, run against the real modules. The lib
 * files open with `import "server-only"`, a build-time no-op that isn't
 * installed for a bare `tsx` run, so we first drop the same empty shim
 * Next.js provides on the server. It stays hermetic: get_plans and the
 * sign-in guard are pure (no DB), and degradedReply is a pure string.
 * ------------------------------------------------------------------ */

// `import "server-only"` resolves to an empty module on the server. Provide it
// (idempotently) BEFORE the dynamic imports below so the modules load under tsx.
//
// This checks CONTENT, not just presence, on purpose (2026-08-26): the real
// npm package `server-only` (facebook/react's own marker package, published to
// the registry) can ALSO end up in node_modules as an unrelated dependency's
// transitive dependency — e.g. `@paypal/react-paypal-js` depends on it for an
// entry point (`v6/server.js`) this codebase never imports. Its DEFAULT export
// condition unconditionally throws "This module cannot be imported from a
// Client Component…" (it only resolves to a no-op under the `react-server`
// export condition, which a bare `tsx` run never sets). A presence-only check
// would find that real package's `index.js` already sitting at this path and
// skip writing our shim over it — passing under `npm ci` today, then breaking
// the instant an unrelated dependency bump makes `server-only` a real installed
// package, exactly as it did here. Checking content makes ours win regardless.
const shimDir = join(import.meta.dirname, "..", "node_modules", "server-only");
const shimIndexPath = join(shimDir, "index.js");
const OUR_SHIM = "module.exports = {};\n";
if (!existsSync(shimIndexPath) || readFileSync(shimIndexPath, "utf8") !== OUR_SHIM) {
