#!/usr/bin/env tsx
// Fly a finished build's jar through the SAME gate code the worker uses (provisionEngine -> planGateFlight -> runTestFlight
// -> gateChecks / gateVerdict) on node-2, and print the per-check result. Usage:
//   CYRUS_MANAGED_PLUGIN_DIR=/tank/cyrus-managed npx tsx scripts/cyrus/tf-engine-flight.ts <jar> <build.json> [--no-engine]
// <build.json> is the modbuilder service's GET /builds/<id> record (mcVersion, pluginName, commands, safety).
import { readFileSync, writeFileSync, mkdtempSync } from "node:fs";
import { createHash } from "node:crypto";
import { tmpdir } from "node:os";
import path from "node:path";
import { provisionEngine } from "../../lib/cyrus/testflight/engine";
import { gateChecks, gateVerdict, planGateFlight, type GateArtifacts, type GateBuild } from "../../lib/cyrus/testflight/gate";
import { runTestFlight } from "../../lib/cyrus/testflight/client";
import { summarize } from "../../lib/cyrus/testflight/summary";

async function main() {
  const [jarPath, buildJson] = process.argv.slice(2);
  const noEngine = process.argv.includes("--no-engine");
  const rec = JSON.parse(readFileSync(buildJson, "utf8"));
  const jar = readFileSync(jarPath);
  const b: GateBuild = { id: rec.id, mcVersion: rec.mcVersion, pluginName: rec.pluginName, jarSha256: createHash("sha256").update(jar).digest("hex"), result: rec.result ?? { safety: rec.safety, commands: rec.commands } };
  const dir = mkdtempSync(path.join(tmpdir(), "tf-engine-"));
  const prov = noEngine ? null : await provisionEngine({ jar, mcVersion: b.mcVersion });
  let engine: GateArtifacts["engine"] = null;
  if (prov) {
    let localPath: string | undefined;
    if (prov.jar && !prov.unavailable) { localPath = path.join(dir, "BetterModel.jar"); writeFileSync(localPath, prov.jar.bytes); }
    engine = { name: prov.name, reason: prov.reason, ...(prov.unavailable ? { unavailable: prov.unavailable } : {}), version: prov.version, ...(localPath ? { localPath, sha256: prov.jar!.sha256 } : {}), seeds: prov.seeds, files: prov.files, notes: prov.notes };
  }
  const art: GateArtifacts = { jarPath, datapacks: [], engine };
  const plan = planGateFlight(b, art);
  console.log(`build ${b.id} ${b.pluginName} on ${b.mcVersion}; engine: ${prov ? `${prov.name} ${prov.version ?? ""} (${prov.reason})${prov.unavailable ? " UNAVAILABLE: " + prov.unavailable : ""}` : "none needed"}`);
  if (!plan.ok) { console.log("NOT RUN:", plan.reason); return; }
  let res;
  for (let i = 0; ; i++) {
    res = await runTestFlight(plan.spec);
    if (res.report.status !== "busy" || i >= 40) break;
    await new Promise((r) => setTimeout(r, 30000));
  }
  const checks = gateChecks(b, res.report, res.summary, { commands: plan.commands, datapacks: 0, engine: engine?.localPath ? engine.name : null, pluginName: b.pluginName });
  const v = gateVerdict(res.summary, checks);
  console.log(JSON.stringify({ verdict: v.verdict, label: v.label, overall: res.summary.overall, reasons: res.summary.reasons, checks, bootMs: res.report.bootMs, peakRssKb: res.report.peakRssKb }, null, 1));
  for (const c of res.report.checks) if (["plugins_enabled", "startup_log_clean"].includes(c.id)) console.log(`--- ${c.id} ${c.status}\n` + c.evidence.slice(0, 14).map((e) => "  " + e.slice(0, 260)).join("\n"));
}
main().catch((e) => { console.error(e); process.exit(2); });
EOF
